import { existsSync } from "node:fs";
import starlight from "@astrojs/starlight";
import { defineConfig } from "astro/config";
import mermaid from "astro-mermaid";
import starlightAutoSidebar from "starlight-auto-sidebar";
import starlightLinksValidator from "starlight-links-validator";

// A section's sidebar: its written pages, ordered by `sidebar.order` and then by slug, followed by
// its generated Reference group when scripts/generate.ts has written one. Reference is a group of
// its own after the autogenerated pages, rather than a subdirectory sorted among them, so it is
// last however the pages are ordered; generate.ts hides the directory from the section's own
// autogenerated list with `hidden: true` in its `_meta.yml` (starlight-auto-sidebar).
function section(label, directory) {
  const items = [{ autogenerate: { directory } }];
  const reference = `${directory}/reference`;
  if (existsSync(new URL(`./src/content/docs/${reference}`, import.meta.url))) {
    items.push({ label: "Reference", items: [{ autogenerate: { directory: reference } }] });
  }
  return { label, items };
}

// Published by .github/workflows/docs.yaml to GitHub Pages at https://sjawhar.github.io/legion/.
export default defineConfig({
  site: "https://sjawhar.github.io",
  base: "/legion",
  integrations: [
    // astro-mermaid must come before Starlight so it sees the ```mermaid fences first.
    mermaid({ autoTheme: true, enableLog: false }),
    starlight({
      title: "Legion",
      description:
        "Documentation for Legion, which runs coding agents on Dispatch issues; Dispatch, where those issues and every human decision live; and the Secrets Broker, which gives agents credentials a human approved.",
      social: [{ icon: "github", label: "GitHub", href: "https://github.com/sjawhar/legion" }],
      editLink: { baseUrl: "https://github.com/sjawhar/legion/edit/main/docs/site/" },
      sidebar: [
        { label: "Overview", items: ["index", "how-it-fits"] },
        section("Legion", "legion"),
        section("Dispatch", "dispatch"),
        section("Secrets Broker", "broker"),
        "contributing",
      ],
      plugins: [starlightLinksValidator(), starlightAutoSidebar()],
    }),
  ],
});
